package com.mutang.xunxi;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Bundle;
import android.webkit.*;
import android.widget.*;
import android.view.*;
import org.jsoup.nodes.Entities;

public final class ReaderActivity extends Activity {
    WebView web;ProgressBar progress;TextView title,status;String original,heading;boolean active=true;
    int d(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);original=getIntent().getStringExtra("url");heading=getIntent().getStringExtra("title");if(!ArticleReader.webUrl(original)){finish();return;}
        getWindow().setStatusBarColor(MainActivity.BG);getWindow().setNavigationBarColor(MainActivity.CARD);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(MainActivity.BG);root.setOnApplyWindowInsetsListener((v,i)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets b=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(b.left,b.top,b.right,b.bottom);}else v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(root);
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(d(12),d(8),d(12),d(8));Button back=new Button(this);back.setText("‹ 返回");back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(-2,-2));title=new TextView(this);title.setText("阅读");title.setTextColor(MainActivity.TEXT);title.setTextSize(19);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setGravity(Gravity.CENTER);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button source=new Button(this);source.setText("原文 ↗");source.setOnClickListener(v->external(original,false));bar.addView(source,new LinearLayout.LayoutParams(-2,-2));root.addView(bar);
        progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);root.addView(progress,new LinearLayout.LayoutParams(-1,d(3)));
        status=new TextView(this);status.setText("正在提取正文…");status.setTextSize(14);status.setTextColor(MainActivity.MUTED);status.setGravity(Gravity.CENTER);status.setPadding(d(16),d(16),d(16),d(16));root.addView(status,new LinearLayout.LayoutParams(-1,-2));web=new WebView(this);web.setBackgroundColor(MainActivity.BG);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setDomStorageEnabled(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);if(android.os.Build.VERSION.SDK_INT>=26)settings.setSafeBrowsingEnabled(true);settings.setBuiltInZoomControls(true);settings.setDisplayZoomControls(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
        web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){if(r.isForMainFrame()&&r.hasGesture()&&ArticleReader.webUrl(r.getUrl().toString()))external(r.getUrl().toString(),false);return true;}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));
        new Thread(()->{try{ArticleReader.Result result=ArticleReader.read(original);runOnUiThread(()->{if(!active||isFinishing())return;show(result);});}catch(Exception e){runOnUiThread(()->{if(active&&!isFinishing()){progress.setVisibility(View.GONE);status.setText("未能识别正文，正在打开原文…");external(original,true);}});}},"xunji-reader").start();}
    void show(ArticleReader.Result r){String name=heading==null||heading.trim().isEmpty()?r.title:heading;String safeTitle=Entities.escape(name==null?"":name);String host=Entities.escape(Collector.host(r.url));String html="<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; img-src https: http:; style-src 'unsafe-inline';\"><style>body{background:#f5f7f4;color:#172e29;font-family:sans-serif;font-size:17px;line-height:1.9;padding:18px;overflow-wrap:anywhere;margin:0}h1{font-size:25px;line-height:1.35;margin:10px 0}h2,h3{line-height:1.45}p{margin:0 0 1em}img{max-width:100%;height:auto;border-radius:8px}a{color:#24745f}blockquote{border-left:3px solid #24745f;padding-left:12px;margin-left:0;color:#52645a}pre{white-space:pre-wrap;background:#e1efe7;padding:12px;border-radius:8px}table{display:block;overflow-x:auto;border-collapse:collapse;max-width:100%}td,th{border:1px solid #bdccc1;padding:8px}small{color:#64756e}hr{border:0;border-top:1px solid #d5e0d8}</style></head><body><h1>"+safeTitle+"</h1><small>"+host+" · 应用内阅读</small><hr>"+r.html+"</body></html>";web.loadDataWithBaseURL(r.url,html,"text/html","UTF-8",null);progress.setVisibility(View.GONE);status.setVisibility(View.GONE);}
    void external(String url,boolean close){if(!ArticleReader.webUrl(url))return;try{if(close)Toast.makeText(this,"无法在应用内读取，已打开原文",Toast.LENGTH_SHORT).show();startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));if(close)finish();}catch(Exception e){status.setVisibility(View.VISIBLE);status.setText("无法打开原文，请检查是否已安装浏览器。");}}
    @Override protected void onDestroy(){active=false;if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}
